cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

// Cover visibility, ownership, roles and idempotence with nonempty audit state.
for (const role of ['admin', 'editor', 'viewer']) {
  for (const owner of ['u', 'other']) {
    for (const tenant of ['a', 'foreign']) {
      for (const deleted of [false, true]) {
        for (const archived of [false, true]) {
          const document = { id: 'one', tenant, owner, deleted, archived };
          const untouched = { id: 'two', tenant: 'a', owner: 'u', deleted: false, archived: false };
          const repo = new DocumentRepository([document, untouched]);
          repo.audit.push({ actor: 'previous', document: 'previous' });
          const service = new DocumentService(repo);
          const actor = { tenant: 'a', user: 'u', role };
          const beforeDocuments = structuredClone(repo.documents);
          const beforeAudit = structuredClone(repo.audit);
          const error = deleted || tenant !== actor.tenant
            ? 'not found'
            : role === 'viewer' || (role === 'editor' && owner !== actor.user)
              ? 'forbidden'
              : undefined;

          if (error) {
            assert.throws(() => service.archive(actor, 'one'), { message: error });
            assert.deepEqual(repo.documents, beforeDocuments);
            assert.deepEqual(repo.audit, beforeAudit);
          } else {
            service.archive(actor, 'one');
            assert.deepEqual(repo.documents, [{ ...document, archived: true }, beforeDocuments[1]]);
            assert.deepEqual(repo.audit, archived
              ? beforeAudit
              : [...beforeAudit, { actor: 'u', document: 'one' }]);
            const afterAudit = structuredClone(repo.audit);
            service.archive(actor, 'one');
            assert.deepEqual(repo.audit, afterAudit);
          }

          const currentDocuments = structuredClone(repo.documents);
          const currentAudit = structuredClone(repo.audit);
          assert.throws(() => service.archive(actor, 'missing'), { message: 'not found' });
          assert.deepEqual(repo.documents, currentDocuments);
          assert.deepEqual(repo.audit, currentAudit);
        }
      }
    }
  }
}
EOF
tsc -p tsconfig.json && node checks/public.cjs

